import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 연계 구분 값 (link_log.link_type)
const LINK_TYPE = 'SUBMIT';
// 가정: 신고 가능한 현재 상태 (작성 중, 실패 후 재신고)
const SUBMITTABLE = ['DRAFT', 'FAILURE'];

@Controller('api/v1')
export class FnSfr02302Controller {
  @Post('/tax-filings/:taxFilingId/submit')
  @HttpCode(200)
  async submitTaxFiling(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    checks.inputOf(req.body);
    const idText = req.params['taxFilingId'];
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT tax_filing_id AS "taxFilingId", filing_type AS "filingType", attribution_month AS "attributionMonth", payment_month AS "paymentMonth", submission_year AS "submissionYear", filing_status AS "filingStatus", filed_at AS "filedAt", result_message AS "resultMessage", receipt_number AS "receiptNumber" FROM tax_filing WHERE tax_filing_id = CAST(:id AS bigint) FOR UPDATE',
        { id: idText },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'TAX_FILING_NOT_FOUND', '신고서를 찾을 수 없습니다.');
      }
      const filing = rows[0];
      if (!SUBMITTABLE.includes(filing.filingStatus)) {
        throw new ApiError(409, 'INVALID_STATE', '이미 신고가 완료된 신고서입니다.');
      }
      // 가정: 전자파일 규격 검증은 신고서 유형별 필수 기간 값의 형식으로 한다
      const monthOk = (v: unknown) => typeof v === 'string' && /^\d{4}(0[1-9]|1[0-2])$/.test(v);
      const yearOk = (v: unknown) => typeof v === 'string' && /^\d{4}$/.test(v);
      let period = '';
      if (filing.filingType === 'SUBMISSION_SUMMARY' || filing.filingType === 'PAYMENT_MEDIA') {
        if (!yearOk(filing.submissionYear)) {
          throw new ApiError(422, 'ELECTRONIC_FILE_VALIDATION_FAILED', '제출 대상 연도가 전자파일 규격에 맞지 않습니다.');
        }
        period = filing.submissionYear;
      } else {
        if (!monthOk(filing.attributionMonth) || !monthOk(filing.paymentMonth)) {
          throw new ApiError(422, 'ELECTRONIC_FILE_VALIDATION_FAILED', '귀속연월·지급연월이 전자파일 규격(YYYYMM)에 맞지 않습니다.');
        }
        period = filing.attributionMonth + '_' + filing.paymentMonth;
      }
      // 가정: 전자파일 이름 규칙
      const electronicFileName = 'NTS_' + filing.filingType + '_' + period + '_' + idText + '.txt';
      await db.execute(
        'INSERT INTO link_log (requester_id, link_target, link_type, status, requested_at, request_summary, created_at, updated_at) VALUES (CAST(:userId AS bigint), :target, :linkType, :status, now(), :summary, now(), now())',
        {
          userId: user.id,
          target: 'NTS_EFILING',
          linkType: LINK_TYPE,
          status: 'REQUESTED',
          summary: electronicFileName,
        },
      );
      // TODO(질문): 국세청 연계 호출 방식과 접수 결과(접수번호·회신 메시지)의 출처가 입력에 없어 SUCCESS/FAILURE 반영과 502 NTS_LINK_FAILED 처리는 구현하지 못했다.
      return {
        taxFilingId: filing.taxFilingId,
        filingStatus: filing.filingStatus,
        filedAt: filing.filedAt,
        resultMessage: filing.resultMessage,
        receiptNumber: filing.receiptNumber,
        electronicFileName,
      };
    });
  }
}

