import { useState } from 'react';
import { call, Band, Badge, DataTable, DateText, Drawer, Field, Form, LookupSelect, RefName } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02302Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [taxFilingId, setTaxFilingId] = useState<number | string>('');

  async function submit() {
    if (taxFilingId === '') {
      throw new Error('신고할 신고서를 선택해 주세요.');
    }
    const res = await call('POST', '/tax-filings/' + taxFilingId + '/submit', role, {});
    setResults([res, ...results.filter((r) => r.taxFilingId !== res.taxFilingId)]);
    notify('전자파일 신고를 처리했습니다.');
    setOpen(false);
    setTaxFilingId('');
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>국세청 원천세 전자파일 신고</h2>
        <Band total={results.length}>
          <button onClick={() => setOpen(true)}>신고 처리</button>
        </Band>
        <DataTable
          columns={[
            { key: 'taxFilingId', label: '세무 신고서', render: (r) => <RefName table="tax_filing" role={role} value={r.taxFilingId} /> },
            { key: 'filingStatus', label: '신고 상태', render: (r) => <Badge value={r.filingStatus} /> },
            { key: 'filedAt', label: '전자신고 일시', render: (r) => <DateText value={r.filedAt} time /> },
            { key: 'receiptNumber', label: '접수번호' },
            { key: 'electronicFileName', label: '생성된 국세청 전자파일 이름' },
          ]}
          rows={results}
          empty="아직 처리한 신고가 없습니다. 신고 처리 버튼으로 신고서를 선택해 주세요."
        />
      </section>
      {open && (
        <Drawer title="전자파일 신고" onClose={() => setOpen(false)}>
          <Form
            onSubmit={submit}
            submit="신고하기"
            note="신고하면 국세청 규격 전자파일을 생성하며, 접수 결과는 신고서에 기록됩니다."
          >
            <Field label="세무 신고서 ID" required wide>
              <LookupSelect table="tax_filing" role={role} value={taxFilingId} onChange={setTaxFilingId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
